using System;
using System.Collections.Generic;
using Astrea.GameElements;
using LittleLeo;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

public class ChooseDiceAction : BattleAction
{
	[Header("Dice To Select")]
	[SerializeField]
	private bool overrideDiceToSelectAmount;

	[SerializeField]
	[ShowIf("overrideDiceToSelectAmount")]
	private int diceToSelectAmount;

	[NonSerialized]
	protected List<DiceInstance> diceList = new List<DiceInstance>();

	public bool OverrideDiceToSelectAmount => overrideDiceToSelectAmount;

	public virtual bool CheckCondition(DiceInstance diceInstance)
	{
		return true;
	}

	public virtual void ActionSelected(int amount)
	{
		DiceActionLogic_ChooseDice diceActionLogic_ChooseDice = GetDiceActionLogic() as DiceActionLogic_ChooseDice;
		ReferenceSingleton<GameStateManager>.Instance.SetState(diceActionLogic_ChooseDice.ChooseDicesState);
		ResetVariables();
	}

	public virtual void ActionCanceled()
	{
	}

	public int GetDiceSelectionAmount(ActionFace actionFace)
	{
		if (overrideDiceToSelectAmount)
		{
			return diceToSelectAmount;
		}
		return GetNonOverrideDiceToSelectAmount(actionFace);
	}

	public virtual int GetNonOverrideDiceToSelectAmount(ActionFace actionFace)
	{
		return actionFace.ModifiedActionValue;
	}

	public virtual void ResetVariables()
	{
		diceList.Clear();
	}

	public virtual void DiceSelected(DiceInstance diceInstance)
	{
		diceList.Add(diceInstance);
	}

	public virtual void DiceDeselected(DiceInstance diceInstance)
	{
		diceList.Remove(diceInstance);
	}

	public virtual bool DiceDeselectedTurnOffCastButton()
	{
		return diceList.Count == 0;
	}

	protected void CastWithPossibleRandomPurifyAsSecondAction()
	{
		Debug.Log("CastWithPossibleRandomPurifyAsSecondAction - Current State: " + ReferenceSingleton<GameStateManager>.Instance.CurrentState.name);
		if (!(ReferenceSingleton<GameStateManager>.Instance.CurrentState != ReferenceSingleton<GameStateManager>.Instance.ChooseDiceOnPoolState) || !(ReferenceSingleton<GameStateManager>.Instance.CurrentState != ReferenceSingleton<GameStateManager>.Instance.NoInteractionState))
		{
			return;
		}
		ReferenceSingleton<GameStateManager>.Instance.TryEnterNoInteractionState();
		InvokeAlternatives.InvokeAfterFrame(ReferenceSingleton<CoroutineHandler>.Instance, delegate
		{
			if (ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.IsAnyActionOnQueuesOrAnyActionsExecuting())
			{
				ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
			}
			else
			{
				ReferenceSingleton<GameStateManager>.Instance.SetChooseActionState();
			}
		});
	}

	protected void SetDiceInstanceGoBackToOriginalPositionAnimation(bool goBackToDiceTray, int i, DiceInstance diceInstance, Action afterGoingBackToOriginalPositionAction = null, bool dontTryToGoToChooseActionState = false)
	{
		if (!goBackToDiceTray)
		{
			return;
		}
		if (i == 0)
		{
			diceInstance.GoBackToOriginalPositionAnimation(returningToHandAfterDrag: false, delegate
			{
				afterGoingBackToOriginalPositionAction?.Invoke();
				if (!dontTryToGoToChooseActionState)
				{
					ReferenceSingleton<GameStateManager>.Instance.TryEnterChooseActionState(WaitForFramesType.NoFrame);
				}
			});
		}
		else
		{
			diceInstance.GoBackToOriginalPositionAnimation(returningToHandAfterDrag: false, afterGoingBackToOriginalPositionAction);
		}
	}

	protected void EndAction(bool goBackToDiceTray)
	{
		if (ReferenceSingleton<GameStateManager>.Instance.CurrentState != ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState)
		{
			ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.NoInteractionState);
		}
		if (goBackToDiceTray)
		{
			ReferenceSingleton<PlayerDiceHandPositioningAnimationManager>.Instance.UpdateDiceInHandPosition();
		}
		else
		{
			ReferenceSingleton<GameStateManager>.Instance.TryEnterChooseActionState(WaitForFramesType.WaitToUpdateCorruptionFrames);
		}
	}
}
